package com.secure.documentwallet;

import android.app.*;import android.content.*;import android.graphics.Color;import android.net.Uri;import android.os.*;import android.view.*;import android.view.inputmethod.InputMethodManager;import android.widget.*;import androidx.activity.result.*;import androidx.activity.result.contract.ActivityResultContracts;import androidx.biometric.*;import androidx.core.content.ContextCompat;import androidx.fragment.app.FragmentActivity;import com.google.mlkit.vision.documentscanner.*;import org.json.*;import java.text.*;import java.util.*;import java.util.concurrent.*;

public class MainActivity extends FragmentActivity {
 private LinearLayout content,documents;private final ExecutorService io=Executors.newSingleThreadExecutor();private final ArrayList<Uri> scanned=new ArrayList<>();private VaultRepository repo;private PinSecurity security;private CloudVault cloud;private boolean scanning;
 private final ActivityResultLauncher<IntentSenderRequest> scanLauncher=registerForActivityResult(new ActivityResultContracts.StartIntentSenderForResult(),this::scanResult);
 @Override public void onCreate(Bundle b){super.onCreate(b);Ui.safeScreen(this);repo=new VaultRepository(this);security=new PinSecurity(this);cloud=new CloudVault(this);lockedScreen();if(security.configured())biometric();else setupPin();}
 private void lockedScreen(){FrameLayout root=new FrameLayout(this);root.setBackgroundColor(Ui.NAVY);LinearLayout box=Ui.column(this);box.setGravity(Gravity.CENTER);TextView icon=Ui.text(this,"▣",64,Color.WHITE);icon.setGravity(Gravity.CENTER);box.addView(icon,new LinearLayout.LayoutParams(-1,Ui.dp(this,92)));TextView name=Ui.text(this,"My Vault",27,Color.WHITE);name.setTypeface(null,android.graphics.Typeface.BOLD);name.setGravity(Gravity.CENTER);box.addView(name);TextView sub=Ui.text(this,"Your Important Documents · Encrypted On This Phone",14,0xffb8d8cf);sub.setGravity(Gravity.CENTER);sub.setPadding(Ui.dp(this,26),Ui.dp(this,10),Ui.dp(this,26),0);box.addView(sub);FrameLayout.LayoutParams p=new FrameLayout.LayoutParams(-1,-2,Gravity.CENTER);root.addView(box,p);setContentView(root);}
 private void setupPin(){LinearLayout box=Ui.column(this);box.setPadding(Ui.dp(this,18),Ui.dp(this,4),Ui.dp(this,18),0);TextView note=Ui.text(this,"Create a 6-digit PIN. You will use it together with your fingerprint or face every time you unlock the vault.",14,Ui.MUTED);note.setPadding(0,0,0,Ui.dp(this,14));box.addView(note);EditText first=Ui.field(this,"New 6-digit PIN",true),second=Ui.field(this,"Confirm PIN",true);box.addView(first,new LinearLayout.LayoutParams(-1,Ui.dp(this,54)));LinearLayout.LayoutParams s=new LinearLayout.LayoutParams(-1,Ui.dp(this,54));s.topMargin=Ui.dp(this,10);box.addView(second,s);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Secure Your Vault").setView(box).setCancelable(false).setPositiveButton("Continue",null).create();dialog.setOnShowListener(x->dialog.getButton(-1).setOnClickListener(v->{String a=first.getText().toString(),c=second.getText().toString();if(!a.matches("\\d{6}")){first.setError("Enter exactly 6 digits");return;}if(!a.equals(c)){second.setError("PINs do not match");return;}try{security.set(a);dialog.dismiss();biometric();}catch(Exception e){Ui.toast(this,"Could not secure the PIN");}}));dialog.show();}
 private void biometric(){int available=BiometricManager.from(this).canAuthenticate(BiometricManager.Authenticators.BIOMETRIC_STRONG);if(available!=BiometricManager.BIOMETRIC_SUCCESS){new AlertDialog.Builder(this).setTitle("Biometric Security Required").setMessage("Please enrol a fingerprint or secure face in your phone settings, then return to unlock this vault.").setCancelable(false).setPositiveButton("Open Settings",(d,w)->startActivity(new Intent(android.provider.Settings.ACTION_BIOMETRIC_ENROLL).putExtra(android.provider.Settings.EXTRA_BIOMETRIC_AUTHENTICATORS_ALLOWED,BiometricManager.Authenticators.BIOMETRIC_STRONG))).setNegativeButton("Close App",(d,w)->finish()).show();return;}BiometricPrompt prompt=new BiometricPrompt(this,ContextCompat.getMainExecutor(this),new BiometricPrompt.AuthenticationCallback(){@Override public void onAuthenticationSucceeded(BiometricPrompt.AuthenticationResult r){pinPrompt();}@Override public void onAuthenticationError(int code,CharSequence message){if(code!=BiometricPrompt.ERROR_NEGATIVE_BUTTON)Ui.toast(MainActivity.this,message.toString());}});prompt.authenticate(new BiometricPrompt.PromptInfo.Builder().setTitle("Unlock My Vault").setSubtitle("Confirm your fingerprint or face").setAllowedAuthenticators(BiometricManager.Authenticators.BIOMETRIC_STRONG).setNegativeButtonText("Close").build());}
 private void pinPrompt(){EditText pin=Ui.field(this,"6-digit PIN",true);pin.setGravity(Gravity.CENTER);FrameLayout wrap=new FrameLayout(this);wrap.setPadding(Ui.dp(this,22),Ui.dp(this,8),Ui.dp(this,22),0);wrap.addView(pin,new FrameLayout.LayoutParams(-1,Ui.dp(this,58)));AlertDialog d=new AlertDialog.Builder(this).setTitle("Enter Your PIN").setMessage("Biometric confirmed. Complete the second security step.").setView(wrap).setCancelable(false).setPositiveButton("Unlock",null).setNegativeButton("Close App",(x,w)->finish()).create();d.setOnShowListener(x->{d.getButton(-1).setOnClickListener(v->{String value=pin.getText().toString();if(security.verify(value)){try{Session.unlock(value,security.vaultSalt());d.dismiss();home();}catch(Exception e){Ui.toast(this,"Could not unlock encryption");}}else{pin.setText("");pin.setError("Incorrect PIN");}});pin.requestFocus();d.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_VISIBLE);});d.show();}
 private void home(){FrameLayout root=new FrameLayout(this);root.setBackgroundColor(Ui.BG);ScrollView scroll=new ScrollView(this);content=Ui.column(this);content.setPadding(Ui.dp(this,18),Ui.dp(this,18),Ui.dp(this,18),Ui.dp(this,110));scroll.addView(content);root.addView(scroll,new FrameLayout.LayoutParams(-1,-1));TextView scan=Ui.pill(this,"▱  Scan A Document",Ui.TEAL);scan.setElevation(Ui.dp(this,7));scan.setOnClickListener(v->scan());FrameLayout.LayoutParams sp=new FrameLayout.LayoutParams(-1,Ui.dp(this,58),Gravity.BOTTOM);sp.setMargins(Ui.dp(this,42),0,Ui.dp(this,42),Ui.dp(this,28));root.addView(scan,sp);setContentView(root);header();categoryStrip();documents=Ui.column(this);content.addView(documents);load();UpdateManager.check(this,false);}
 private void header(){LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);LinearLayout titles=Ui.column(this);titles.addView(Ui.title(this,"My Vault",29));TextView sub=Ui.text(this,"Private · Encrypted · Available Offline",13,Ui.MUTED);sub.setPadding(0,4,0,0);titles.addView(sub);row.addView(titles,new LinearLayout.LayoutParams(0,-2,1));TextView cloudButton=Ui.text(this,"☁",24,Ui.TEAL);cloudButton.setGravity(Gravity.CENTER);cloudButton.setContentDescription("Cloud Backup And PC Access");cloudButton.setBackground(Ui.bg(Ui.SOFT,Ui.dp(this,23)));cloudButton.setOnClickListener(v->cloudMenu());LinearLayout.LayoutParams cloudParams=new LinearLayout.LayoutParams(Ui.dp(this,46),Ui.dp(this,46));cloudParams.rightMargin=Ui.dp(this,8);row.addView(cloudButton,cloudParams);TextView lock=Ui.text(this,"⌾",26,Color.WHITE);lock.setGravity(Gravity.CENTER);lock.setContentDescription("Lock Vault");lock.setBackground(Ui.bg(Ui.NAVY,Ui.dp(this,23)));lock.setOnClickListener(v->{Session.lock();lockedScreen();biometric();});row.addView(lock,new LinearLayout.LayoutParams(Ui.dp(this,46),Ui.dp(this,46)));content.addView(row);TextView intro=Ui.text(this,"Keep identification, permits, certificates and other essential records together. Scans stay encrypted inside this phone until you choose to export them.",14,Ui.MUTED);intro.setPadding(0,Ui.dp(this,14),0,Ui.dp(this,18));intro.setLineSpacing(0,1.12f);content.addView(intro);}
 private void categoryStrip(){HorizontalScrollView hs=new HorizontalScrollView(this);hs.setHorizontalScrollBarEnabled(false);LinearLayout row=new LinearLayout(this);String[][] cats={{"▣","Identity"},{"◆","Permits"},{"✓","Certificates"},{"●","Other"}};for(String[] c:cats){LinearLayout card=Ui.column(this);card.setGravity(Gravity.CENTER);card.setBackground(Ui.bg(Color.WHITE,Ui.dp(this,16)));card.setElevation(Ui.dp(this,2));TextView i=Ui.text(this,c[0],25,Ui.TEAL);i.setGravity(Gravity.CENTER);card.addView(i);TextView t=Ui.text(this,c[1],13,Ui.INK);t.setGravity(Gravity.CENTER);t.setTypeface(null,android.graphics.Typeface.BOLD);card.addView(t);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(Ui.dp(this,112),Ui.dp(this,82));p.setMargins(0,0,Ui.dp(this,10),0);row.addView(card,p);}hs.addView(row);content.addView(hs,new LinearLayout.LayoutParams(-1,Ui.dp(this,92)));TextView label=Ui.title(this,"Your Documents",19);label.setPadding(0,Ui.dp(this,18),0,Ui.dp(this,10));content.addView(label);}
 private void load(){documents.removeAllViews();io.execute(()->{try{JSONArray a=repo.all();runOnUiThread(()->render(a));}catch(Exception e){runOnUiThread(()->Ui.toast(this,"Could not open the encrypted vault"));}});}
 private void render(JSONArray a){documents.removeAllViews();if(a.length()==0){LinearLayout empty=Ui.column(this);empty.setGravity(Gravity.CENTER);empty.setPadding(Ui.dp(this,20),Ui.dp(this,36),Ui.dp(this,20),Ui.dp(this,36));empty.setBackground(Ui.stroke(Color.WHITE,Ui.dp(this,1),0xffd4e1dd,Ui.dp(this,18)));TextView icon=Ui.text(this,"▱",44,Ui.TEAL);icon.setGravity(Gravity.CENTER);empty.addView(icon);TextView title=Ui.title(this,"Your Wallet Is Ready",18);title.setGravity(Gravity.CENTER);empty.addView(title);TextView body=Ui.text(this,"Scan your first document. Automatic capture will find the edges and clean the image for you.",14,Ui.MUTED);body.setGravity(Gravity.CENTER);body.setPadding(Ui.dp(this,12),Ui.dp(this,8),Ui.dp(this,12),0);empty.addView(body);documents.addView(empty,new LinearLayout.LayoutParams(-1,-2));return;}for(int i=0;i<a.length();i++){JSONObject d=a.optJSONObject(i);LinearLayout card=new LinearLayout(this);card.setGravity(Gravity.CENTER_VERTICAL);card.setPadding(Ui.dp(this,13),Ui.dp(this,11),Ui.dp(this,13),Ui.dp(this,11));card.setBackground(Ui.bg(Color.WHITE,Ui.dp(this,16)));card.setElevation(Ui.dp(this,2));TextView icon=Ui.text(this,"▤",27,Color.WHITE);icon.setGravity(Gravity.CENTER);icon.setBackground(Ui.bg(Ui.TEAL,Ui.dp(this,14)));card.addView(icon,new LinearLayout.LayoutParams(Ui.dp(this,54),Ui.dp(this,54)));LinearLayout words=Ui.column(this);words.setPadding(Ui.dp(this,13),0,0,0);words.addView(Ui.title(this,d.optString("title","Document"),16));String date=new SimpleDateFormat("dd MMM yyyy",Locale.getDefault()).format(new Date(d.optLong("createdAt")));words.addView(Ui.text(this,d.optString("category","Other")+"  ·  "+d.optJSONArray("pages").length()+" page"+(d.optJSONArray("pages").length()==1?"":"s")+"  ·  "+date,12,Ui.MUTED));card.addView(words,new LinearLayout.LayoutParams(0,-2,1));TextView arrow=Ui.text(this,"›",29,Ui.MUTED);card.addView(arrow);card.setOnClickListener(v->startActivity(new Intent(this,DocumentActivity.class).putExtra("id",d.optString("id"))));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,Ui.dp(this,78));p.bottomMargin=Ui.dp(this,10);documents.addView(card,p);}}
 private void scan(){GmsDocumentScannerOptions options=new GmsDocumentScannerOptions.Builder().setGalleryImportAllowed(true).setPageLimit(20).setResultFormats(GmsDocumentScannerOptions.RESULT_FORMAT_JPEG,GmsDocumentScannerOptions.RESULT_FORMAT_PDF).setScannerMode(GmsDocumentScannerOptions.SCANNER_MODE_FULL).build();scanning=true;GmsDocumentScanning.getClient(options).getStartScanIntent(this).addOnSuccessListener(sender->scanLauncher.launch(new IntentSenderRequest.Builder(sender).build())).addOnFailureListener(e->{scanning=false;Ui.toast(this,"Scanner unavailable: "+e.getMessage());});}
 private void scanResult(ActivityResult activity){scanning=false;if(activity.getResultCode()!=RESULT_OK)return;GmsDocumentScanningResult result=GmsDocumentScanningResult.fromActivityResultIntent(activity.getData());scanned.clear();if(result!=null&&result.getPages()!=null)for(GmsDocumentScanningResult.Page p:result.getPages())scanned.add(p.getImageUri());if(scanned.isEmpty()){Ui.toast(this,"No pages were returned");return;}saveDialog();}
 private void saveDialog(){LinearLayout box=Ui.column(this);box.setPadding(Ui.dp(this,18),Ui.dp(this,5),Ui.dp(this,18),0);EditText title=Ui.field(this,"Document name",false);box.addView(title,new LinearLayout.LayoutParams(-1,Ui.dp(this,54)));Spinner category=new Spinner(this);String[] values={"Identity","Driver Permit / Licence","Certificate","Medical","Financial","Other"};category.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,values));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,Ui.dp(this,54));cp.topMargin=Ui.dp(this,10);box.addView(category,cp);TextView pages=Ui.text(this,scanned.size()+" cleaned page"+(scanned.size()==1?"":"s")+" ready to encrypt",13,Ui.TEAL);pages.setPadding(2,Ui.dp(this,12),0,0);box.addView(pages);AlertDialog d=new AlertDialog.Builder(this).setTitle("Save To My Vault").setView(box).setNegativeButton("Discard",null).setPositiveButton("Encrypt & Save",null).create();d.setOnShowListener(x->d.getButton(-1).setOnClickListener(v->{String name=title.getText().toString().trim();if(name.isEmpty()){title.setError("Give this document a name");return;}d.getButton(-1).setEnabled(false);io.execute(()->{try{repo.add(name,values[category.getSelectedItemPosition()],new ArrayList<>(scanned));runOnUiThread(()->{d.dismiss();scanned.clear();load();Ui.toast(this,"Document encrypted and saved");});}catch(Exception e){runOnUiThread(()->{d.getButton(-1).setEnabled(true);Ui.toast(this,"Could not save the scan");});}});}));d.show();title.requestFocus();d.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);}
 private void cloudMenu(){String[] options={"Back Up Encrypted Vault","Restore Encrypted Vault","Open PC Portal","How PC Access Works","Check For Updates"};new AlertDialog.Builder(this).setTitle("My Vault Settings").setItems(options,(d,i)->{if(i==2)startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse("https://badimps.github.io/secure-document-wallet/")));else if(i==3)new AlertDialog.Builder(this).setTitle("Two-Step PC Access").setMessage("The private web portal sends a one-time code to your email, then asks for this vault PIN. Files remain encrypted while stored online.").setPositiveButton("OK",null).show();else if(i==4)UpdateManager.check(this,true);else authenticateCloud(i==0);}).show();}
 private void authenticateCloud(boolean backup){EditText email=Ui.field(this,"Email address",false);email.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS);FrameLayout wrap=new FrameLayout(this);wrap.setPadding(Ui.dp(this,20),Ui.dp(this,8),Ui.dp(this,20),0);wrap.addView(email,new FrameLayout.LayoutParams(-1,Ui.dp(this,56)));AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Send Verification Code").setMessage("A free one-time code will be emailed to the address you enter.").setView(wrap).setNegativeButton("Cancel",null).setPositiveButton("Send Code",null).create();dialog.setOnShowListener(x->dialog.getButton(-1).setOnClickListener(v->{String address=email.getText().toString().trim();if(!android.util.Patterns.EMAIL_ADDRESS.matcher(address).matches()){email.setError("Enter a valid email");return;}dialog.getButton(-1).setEnabled(false);io.execute(()->{try{cloud.sendCode(address);runOnUiThread(()->{dialog.dismiss();codeDialog(address,backup);});}catch(Exception e){runOnUiThread(()->{dialog.getButton(-1).setEnabled(true);Ui.toast(this,e.getMessage());});}});}));dialog.show();}
 private void codeDialog(String email,boolean backup){EditText code=Ui.field(this,"Code Or Verification Link",false);code.setGravity(Gravity.CENTER);FrameLayout wrap=new FrameLayout(this);wrap.setPadding(Ui.dp(this,20),Ui.dp(this,8),Ui.dp(this,20),0);wrap.addView(code,new FrameLayout.LayoutParams(-1,Ui.dp(this,56)));AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Verify Your Email").setMessage("Enter the one-time code sent to "+email+". If the free mailer sends a secure link instead, copy and paste that link here.").setView(wrap).setNegativeButton("Cancel",null).setPositiveButton("Verify",null).create();dialog.setOnShowListener(x->dialog.getButton(-1).setOnClickListener(v->{String token=code.getText().toString().trim();if(token.length()<6){code.setError("Enter the code or secure link");return;}dialog.getButton(-1).setEnabled(false);io.execute(()->{try{cloud.verify(email,token);runOnUiThread(()->{dialog.dismiss();runCloud(backup);});}catch(Exception e){runOnUiThread(()->{dialog.getButton(-1).setEnabled(true);code.setError(e.getMessage());});}});}));dialog.show();}
 private void runCloud(boolean backup){ProgressDialog wait=new ProgressDialog(this);wait.setCancelable(false);wait.setMessage(backup?"Encrypting and backing up…":"Restoring encrypted documents…");wait.show();io.execute(()->{try{int count=backup?cloud.backup(security.vaultSalt()):cloud.restore(security.vaultSalt());runOnUiThread(()->{wait.dismiss();if(!backup)load();Ui.toast(this,(backup?"Cloud backup complete: ":"Cloud restore complete: ")+count+" encrypted files");});}catch(Exception e){runOnUiThread(()->{wait.dismiss();Ui.toast(this,e.getMessage());});}});}
 @Override public boolean dispatchTouchEvent(android.view.MotionEvent event){if(Session.valid())Session.touch();return super.dispatchTouchEvent(event);}
 @Override protected void onResume(){super.onResume();if(content!=null){if(Session.valid())load();else{lockedScreen();biometric();}}}
 @Override protected void onDestroy(){super.onDestroy();io.shutdownNow();}
}
